CREATE TABLE public.account_recovery (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,user_id uuid NOT NULL,hashes jsonb NOT NULL DEFAULT '[]',attempts integer NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,user_id)); GRANT SELECT ON public.account_recovery TO authenticated; GRANT ALL ON public.account_recovery TO service_role; ALTER TABLE public.account_recovery ENABLE ROW LEVEL SECURITY; CREATE POLICY recovery_own_read ON public.account_recovery FOR SELECT TO authenticated USING(false); CREATE TRIGGER audit_account_recovery AFTER INSERT OR UPDATE OR DELETE ON public.account_recovery FOR EACH ROW EXECUTE FUNCTION public.audit_capture(); CREATE OR REPLACE FUNCTION public.audit_recovery_minimise() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.hashes := NEW.hashes; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.recovery_store(_org uuid,_hashes jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_org_member(_org) OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' OR jsonb_array_length(_hashes)<>10 THEN RAISE EXCEPTION 'Verified two-factor session required'; END IF; INSERT INTO public.account_recovery(org_id,user_id,hashes) VALUES(_org,auth.uid(),_hashes) ON CONFLICT(org_id,user_id) DO UPDATE SET hashes=EXCLUDED.hashes,updated_at=now(); END $$; REVOKE ALL ON FUNCTION public.recovery_store(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.recovery_store(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.recovery_attempt(_org uuid,_user uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.account_recovery; BEGIN SELECT * INTO r FROM public.account_recovery WHERE org_id=_org AND user_id=_user FOR UPDATE; IF r.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.org_members WHERE org_id=_org AND user_id=_user AND active) THEN RETURN false; END IF; IF r.window_start < now()-interval '1 hour' THEN r.attempts:=0;r.window_start:=now();END IF; IF r.attempts>=5 THEN RETURN false;END IF; UPDATE public.account_recovery SET attempts=r.attempts+1,window_start=r.window_start WHERE id=r.id; RETURN true; END $$; REVOKE ALL ON FUNCTION public.recovery_attempt(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.recovery_attempt(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.recovery_consume(_org uuid,_user uuid,_hash text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.account_recovery; BEGIN SELECT * INTO r FROM public.account_recovery WHERE org_id=_org AND user_id=_user FOR UPDATE; IF r.id IS NULL OR NOT(r.hashes ? _hash) THEN RETURN false;END IF; UPDATE public.account_recovery SET hashes=hashes-_hash,updated_at=now() WHERE id=r.id;RETURN true;END $$;REVOKE ALL ON FUNCTION public.recovery_consume(uuid,uuid,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.recovery_consume(uuid,uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.audit_minimise(_table text,_row jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _row IS NULL THEN NULL WHEN _table='account_recovery' THEN _row-'hashes' WHEN _table='org_invites' THEN _row-ARRAY['token_hash','email'] WHEN _table='complaints' THEN _row-ARRAY['complainant_name','complainant_email','complainant_phone','customer_ref','vulnerable_note','summary','desired_outcome','holding_reason','root_cause_note','root_cause_category'] WHEN _table='complaint_events' THEN _row-'detail' WHEN _table='letters' THEN _row-ARRAY['subject','body'] WHEN _table='qa_reviews' THEN _row-ARRAY['comments','scorecard'] WHEN _table='notifications' THEN _row-'title' WHEN _table='public_form_submissions' THEN _row-'privacy_notice' ELSE _row END $$;
CREATE OR REPLACE FUNCTION public.organisation_settings_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(NEW.legal_name)) NOT BETWEEN 1 AND 200 OR NEW.base_currency !~ '^[A-Z]{3}$' OR length(NEW.firm_address)>2000 THEN RAISE EXCEPTION 'Invalid organisation settings';END IF;IF NEW.require_2fa AND NOT OLD.require_2fa AND auth.uid() IS NOT NULL AND auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' THEN RAISE EXCEPTION 'Verify your authenticator before requiring 2FA';END IF;RETURN NEW;END $$; CREATE TRIGGER organisation_settings_validation BEFORE UPDATE ON public.organisations FOR EACH ROW EXECUTE FUNCTION public.organisation_settings_guard(); REVOKE INSERT,UPDATE,DELETE ON public.org_invites FROM authenticated,anon; CREATE UNIQUE INDEX org_invite_hash_unique ON public.org_invites(token_hash);